package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import java.util.Objects;
import org.bukkit.Particle;
import org.bukkit.entity.Creeper;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityDamageEvent;

public final class UnstableCreeperBehaviour implements CompiledBehaviour {
    private static final EntityDamageEvent.DamageCause ENTITY_ATTACK = EntityDamageEvent.DamageCause.ENTITY_ATTACK;

    private static final EntityDamageEvent.DamageCause PROJECTILE = EntityDamageEvent.DamageCause.PROJECTILE;

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final Particle END_ROD = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:end_rod");

    private final MobContext context;

    private Cooldown cooldown;

    public UnstableCreeperBehaviour(MobContext context) {
        this.context = context;
        // node #41 function.cooldown
        this.cooldown = new Cooldown();
    }

    @Override
    public void onDamageByEntity(EntityDamageByEntityEvent event) {
        // node #9 event.damage_by_entity
        // node #12 flow.branch
        // node #10 event.damage_by_entity
        final EntityDamageEvent.DamageCause cause = event.getCause();
        if (!(Objects.equals(cause, ENTITY_ATTACK) || Objects.equals(cause, PROJECTILE))) return;
        // node #11 creeper.explode
        ((Creeper) this.context.entity()).explode();
        // node #13
    }

    @Override
    public void onDamageByPlayer(EntityDamageByEntityEvent event) {
        // node #23 event.damage_by_player
        // node #26 flow.branch
        // node #24 event.damage_by_player
        final EntityDamageEvent.DamageCause cause = event.getCause();
        if (!(Objects.equals(cause, ENTITY_ATTACK) || Objects.equals(cause, PROJECTILE))) return;
        // node #25 creeper.explode
        ((Creeper) this.context.entity()).explode();
        // node #27
    }

    @Override
    public void onSpawn() {
        // node #34 mob.spawn
        // node #36 creeper.mutate
        // node #35 mob.self
        final Creeper self = ((Creeper) this.context.entity());
        self.setExplosionRadius(10);
        // node #37 creeper.mutate
        self.setPowered(true);
        // node #38 creeper.mutate
        self.setMaxFuseTicks(50);
        // node #39
    }

    @Override
    public void onTick() {
        // node #49 mob.tick
        // node #53 flow.branch
        // node #50 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(250.0d));
        if (!cooldown) return;
        // node #52 world.spawn_particle
        // node #51 mob.self
        final Creeper self = ((Creeper) this.context.entity());
        BukkitRuntime.particles(this.context, self.getWorld(), END_ROD, self.getEyeLocation(), 2, 1.5d, 1.0d, 1.5d, null);
        // node #54
    }
}
